import { Navigate, Route, Routes } from 'react-router-dom'
import { AuthProvider } from './auth/AuthProvider.jsx'
import { useAuth } from './auth/useAuth.js'
import { ClassProvider } from './class/ClassProvider.jsx'
import { Layout } from './components/Layout.jsx'
import { LoginPage } from './pages/LoginPage.jsx'
import { ChangePasswordPage } from './pages/ChangePasswordPage.jsx'
import { DashboardPage } from './pages/DashboardPage.jsx'
import { StudentsPage } from './pages/StudentsPage.jsx'
import { AttendancePage } from './pages/AttendancePage.jsx'
import { FeesPage } from './pages/FeesPage.jsx'
import { ExamsPage } from './pages/ExamsPage.jsx'
import { ResultsPage } from './pages/ResultsPage.jsx'
import { StudentProfilePage } from './pages/StudentProfilePage.jsx'
import { TeachersPage } from './pages/TeachersPage.jsx'

function AuthenticatedOnly({ children }) {
  const { token } = useAuth()
  if (!token) return <Navigate to="/login" replace />
  return children
}

function Protected({ children }) {
  const { token, user } = useAuth()
  if (!token) return <Navigate to="/login" replace />
  if (user?.role === 'teacher' && user?.must_change_password) {
    return <Navigate to="/change-password" replace />
  }
  return children
}

function GuestOnly({ children }) {
  const { token, user } = useAuth()
  if (!token) return children
  if (user?.role === 'teacher' && user?.must_change_password) {
    return <Navigate to="/change-password" replace />
  }
  return <Navigate to={user?.role === 'student' ? '/student-profile' : '/'} replace />
}

function RequireRoles({ roles, children }) {
  const { user } = useAuth()
  if (!user) return <Navigate to="/login" replace />
  return roles.includes(user.role) ? children : <Navigate to={user.role === 'student' ? '/student-profile' : '/'} replace />
}

function HomePage() {
  const { user } = useAuth()
  if (user?.role === 'student') return <Navigate to="/student-profile" replace />
  return <DashboardPage />
}

export default function App() {
  return (
    <AuthProvider>
      <ClassProvider>
        <Routes>
          <Route
            path="/login"
            element={
              <GuestOnly>
                <LoginPage />
              </GuestOnly>
            }
          />
          <Route
            path="/change-password"
            element={
              <AuthenticatedOnly>
                <ChangePasswordPage />
              </AuthenticatedOnly>
            }
          />
          <Route
            path="/"
            element={
              <Protected>
                <Layout />
              </Protected>
            }
          >
            <Route index element={<HomePage />} />
            <Route
              path="teachers"
              element={
                <RequireRoles roles={['admin']}>
                  <TeachersPage />
                </RequireRoles>
              }
            />
            <Route
              path="students"
              element={
                <RequireRoles roles={['admin', 'teacher']}>
                  <StudentsPage />
                </RequireRoles>
              }
            />
            <Route
              path="attendance"
              element={
                <RequireRoles roles={['admin', 'teacher']}>
                  <AttendancePage />
                </RequireRoles>
              }
            />
            <Route
              path="fees"
              element={
                <RequireRoles roles={['admin', 'teacher']}>
                  <FeesPage />
                </RequireRoles>
              }
            />
            <Route
              path="exams"
              element={
                <RequireRoles roles={['admin', 'teacher']}>
                  <ExamsPage />
                </RequireRoles>
              }
            />
            <Route
              path="results"
              element={
                <RequireRoles roles={['admin', 'teacher']}>
                  <ResultsPage />
                </RequireRoles>
              }
            />
            <Route path="student-profile" element={<StudentProfilePage />} />
            <Route path="student-profile/:admissionId" element={<StudentProfilePage />} />
          </Route>
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </ClassProvider>
    </AuthProvider>
  )
}
